// TypeScript port of /workspace/calorie-tracker/internal/parser/parser.go
// (backend commit ea9dd85). Same rules.json + dishes.json; parity is enforced by
// __tests__/parser.test.ts against outputs generated by the Go parser
// (scripts/sync-dishes.sh -> src/data/golden.json). Keep this a line-by-line
// mirror of the Go code whenever either side changes.

export type Unit = 'count' | 'piece' | 'katori' | 'spoon' | 'plate' | 'glass' | 'gram' | string;
export type OilLevel = '' | 'less' | 'normal' | 'extra';

export interface Part { dish_id: string; qty: number; unit: string }
export interface Dish {
  id: string; name: string; aliases: string[]; unit: Unit; portion_grams: number;
  kcal: number; kcal_low: number; kcal_high: number;
  protein_g: number; protein_low: number; protein_high: number;
  oil_sensitive: boolean; source: string; source_note: string; is_estimate?: boolean;
  diet?: 'veg' | 'egg' | 'nonveg' | string; category?: string; brand?: string; version?: number;
  carbs_g?: number; fat_g?: number; macro_note?: string; needs_verification?: boolean;
  piece_grams?: number; parts?: Part[]; needs_confirm?: boolean;
}
interface UnitRule { words: string[]; grams: number; as?: string; factor?: number }
export interface Rules {
  numbers: Record<string, number>; half_suffixes: string[]; units: Record<string, UnitRule>;
  oil_words: Record<string, string[]>; oil_nouns: string[]; oil_suffixes: string[]; small_words: string[]; fat_dishes: string[];
  small_fat_spoons: number; default_fat_spoons: number; extra_fat_spoons: number; max_fat_spoons: number; oil_kcal_per_150g: number;
  fillers: string[]; brand_words: string[]; multiplier_prefixes: string[]; protein_words: Record<string, string>; genitive_words: string[];
  fuzzy_min_len: number; fuzzy_max_dist: number; fuzzy_same_first_letter: boolean;
  devanagari_digits: string; devanagari_words: Record<string, string>;
  generic_protein_dish: Record<string, string>; form_words: string[]; modifier_words: string[]; stuffing_words: string[];
  connectors: string[]; egg_words: string[]; wrap_forms: string[]; generic_wrap_dish: string; eggs_per_portion: Record<string, number>; fuzzy_min_similarity: number;
  unknown_item: { kcal: [number, number, number]; protein_g: [number, number, number]; name: string };
  sanity: { max_item_kcal: number; max_portion_multiple: number; max_count_multiple: number };
  style_words: string[]; stopwords: string[]; min_placeholder_len: number; confidence: Record<string, number>;
  fuzzy_never_to_categories: string[]; typical_sides: Record<string, string[]>;
}
export interface Range { low: number; best: number; high: number }
export interface Alternative { quantity: number; unit: string; kcal: number; label: string }
export interface Item {
  dish_id: string; name: string; matched_text: string; quantity: number; unit: Unit; grams: number;
  oil_level: OilLevel; kcal: Range; protein_g: Range; carbs_g: number; fat_g: number;
  /** table | did_you_mean | generic | ai_estimate */
  source: ItemSource; data_source: string; source_note: string; fuzzy: boolean; from_combo?: string;
  needs_confirmation: boolean;
  /** 0-1 from match quality and context; below rules.confidence.threshold it needs confirmation. flags say why. */
  confidence?: number; flags?: string[];
  alternatives?: Alternative[]; ai_estimate: boolean;
  /** from the user's remembered readings (server parse) */
  learned?: boolean;
}
export type ItemSource = 'table' | 'did_you_mean' | 'generic' | 'ai_estimate';
/** leftover: words/numbers the parser could not use (incl. short/stopword leftovers that never become placeholders). */
export interface ParseResult { items: Item[]; unmatched: string[]; leftover: number }

type It = Item & { explicit?: boolean; generic?: boolean; clause?: number; joined?: boolean; pens?: string[] };
/** Go Item.pen: add a confidence deduction once (copy-on-write). */
const pen = (it: It, f: string) => { if (!it.pens?.includes(f)) it.pens = [...(it.pens ?? []), f]; };
interface Token { w: string; num: number; isN: boolean; sep: boolean; mult: number }
const tok = (p: Partial<Token>): Token => ({ w: '', num: 0, isN: false, sep: false, mult: 0, ...p });
interface Pending { style: string[]; qty: number; hasQty: boolean; unit: string; factor: number; oil: string; small: boolean }
const emptyPending = (): Pending => ({ style: [], qty: 0, hasQty: false, unit: '', factor: 0, oil: '', small: false });

/** Go's math.Round (half away from zero) to d decimals. */
export function round(f: number, d: number): number {
  const m = Math.pow(10, d);
  const x = f * m;
  return (x < 0 ? -Math.round(-x) : Math.round(x)) / m;
}
const fmt = (n: number) => String(n); // == strconv.FormatFloat(f,'f',-1,64) for the ranges we see
const fields = (s: string) => s.split(/\s+/).filter(Boolean);
const runes = (s: string) => Array.from(s);
const NUKTA = '\u093C';
const goParseFloat = (f: string): number | null => {
  const m = /^([+-]?)(inf|infinity)$/i.exec(f);
  if (m) return m[1] === '-' ? -Infinity : Infinity;
  if (/^[+-]?nan$/i.test(f)) return NaN;
  return /^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/.test(f) ? parseFloat(f) : null;
};
const has = (o: object, k: string) => Object.prototype.hasOwnProperty.call(o, k);
const firstByte = (s: string) => new TextEncoder().encode(s)[0];
const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const reNumUnit = /(\d+(?:\.\d+)?)([a-z]+)/g;
const reClean = /[^a-z0-9.½&+*\u0900-\u097F ]+/gu;
const reFrac = /(\d+)\s*\/\s*(\d+)/g;
const reDevWord = /[\u0900-\u097F]+/gu;

export class Parser {
  private dish = new Map<string, Dish>();
  private byID = new Map<string, Dish>();
  private maxLen = 0;
  private byWords = new Map<number, string[]>();
  private unitOf = new Map<string, string>();
  private oilOf = new Map<string, string>();
  private devDigit = new Map<string, string>();
  private small: Set<string>; private oilNoun: Set<string>; private oilSuf: Set<string>;
  private filler: Set<string>; private fat: Set<string>; private genitive: Set<string>;
  private formWord: Set<string>; private modifier: Set<string>; private stuffing: Set<string>; private connector: Set<string>; private eggWord: Set<string>;
  private style: Set<string>; private stop: Set<string>; private noFuzzyCat: Set<string>;
  private reMult: RegExp;

  constructor(private table: Dish[], private r: Rules) {
    for (const d of table) {
      this.byID.set(d.id, d);
      for (let t of [d.name, d.id.replaceAll('_', ' '), ...(d.aliases ?? [])]) {
        t = fields(t.toLowerCase()).join(' ');
        if (this.dish.has(t) || t === '') continue;
        this.dish.set(t, d);
        const n = fields(t).length;
        this.maxLen = Math.max(this.maxLen, n);
        this.byWords.set(n, [...(this.byWords.get(n) ?? []), t]);
      }
    }
    for (const [u, ur] of Object.entries(r.units)) for (const w of ur.words) this.unitOf.set(w, u);
    for (const [lvl, ws] of Object.entries(r.oil_words)) for (const w of ws) this.oilOf.set(w, lvl);
    runes(r.devanagari_digits).forEach((ch, i) => this.devDigit.set(ch, String(i)));
    this.small = new Set(r.small_words); this.oilNoun = new Set(r.oil_nouns); this.oilSuf = new Set(r.oil_suffixes);
    this.fat = new Set(r.fat_dishes); this.genitive = new Set(r.genitive_words);
    this.formWord = new Set(r.form_words); this.modifier = new Set(r.modifier_words); this.stuffing = new Set(r.stuffing_words);
    this.connector = new Set(r.connectors); this.eggWord = new Set(r.egg_words);
    this.style = new Set(r.style_words); this.stop = new Set(r.stopwords); this.noFuzzyCat = new Set(r.fuzzy_never_to_categories);
    this.filler = new Set([...r.fillers, ...r.brand_words]);
    const pre = r.multiplier_prefixes.map(escapeRe).join('|');
    this.reMult = new RegExp(`(?:^|\\s)(?:${pre})\\s*(\\d+(?:\\.\\d+)?)(?:\\s|$)|(?:^|\\s)(\\d+(?:\\.\\d+)?)\\s*(?:x|×)(?:\\s|$)`, 'g');
  }

  dishById(id: string): Dish | undefined { return this.byID.get(id); }
  allDishes(): Dish[] { return this.table; }

  private transliterate(s: string): string {
    s = runes(s).map((ch) => (this.devDigit.has(ch) ? this.devDigit.get(ch)! : ch === NUKTA ? '' : ch)).join('');
    return s.replace(reDevWord, (w) => { const t = this.devWord(w); return ' ' + (t ?? w) + ' '; });
  }
  private devWord(w: string): string | undefined {
    for (const [k, v] of Object.entries(this.r.devanagari_words)) if (k.replaceAll(NUKTA, '') === w) return v;
    return undefined;
  }

  private normalize(s: string): string {
    s = this.transliterate(s).toLowerCase();
    s = s.replace(reFrac, (m, a, b) => (Number(b) === 0 ? m : fmt(Number(a) / Number(b))));
    s = s.replaceAll('½', ' 0.5 ');
    for (let i = 0; i < 2; i++) s = s.replace(this.reMult, (_m, a, b) => ' *' + (a ?? '') + (b ?? '') + ' ');
    s = s.replace(reClean, ' , ');
    s = s.replaceAll('&', ' & ').replaceAll('+', ' + ');
    s = s.replace(reNumUnit, '$1 $2');
    s = ' ' + fields(s).join(' ') + ' ';
    for (const suf of this.r.half_suffixes) s = s.replaceAll(' ' + suf + ' ', ' +0.5 ');
    return s;
  }

  private tokenize(s: string): Token[] {
    const out: Token[] = [];
    for (let f of fields(this.normalize(s))) {
      if (f === ',' || f === '.') { out.push(tok({ sep: true })); continue; }
      if (f.startsWith('*')) {
        const v = goParseFloat(f.slice(1));
        if (v !== null && v > 0) out.push(tok({ mult: v }));
        continue;
      }
      f = f.replace(/^\.+|\.+$/g, '');
      if (f === '') continue;
      if (f === '+0.5') {
        const n = out.length;
        if (n > 0 && out[n - 1].isN) out[n - 1].num += 0.5;
        else out.push(tok({ num: 1.5, isN: true }));
        continue;
      }
      const v = goParseFloat(f);
      if (v !== null) { out.push(tok({ num: v, isN: true })); continue; }
      if (Object.prototype.hasOwnProperty.call(this.r.numbers, f)) { out.push(tok({ w: f, num: this.r.numbers[f], isN: true })); continue; }
      out.push(tok({ w: f }));
    }
    for (let i = 1; i + 1 < out.length; i++) {
      if (this.genitive.has(out[i].w) && out[i - 1].w !== '' && out[i + 1].w !== '') {
        if (this.dish.has(out[i - 1].w + ' ' + out[i + 1].w)) out.splice(i, 1);
      }
    }
    return out;
  }

  private word(t: Token) { return t.w !== '' ? t.w : fmt(t.num); }

  private words(toks: Token[], i: number, n: number): string[] | null {
    if (i + n > toks.length) return null;
    const ws: string[] = [];
    for (const t of toks.slice(i, i + n)) { if (t.sep || t.w === '' || t.mult !== 0) return null; ws.push(t.w); }
    return ws;
  }

  private fuzzyWord(a: string, b: string): boolean {
    if (a === b) return true;
    if (runes(a).length < this.r.fuzzy_min_len || runes(b).length < this.r.fuzzy_min_len) return false;
    if (this.r.fuzzy_same_first_letter && firstByte(a) !== firstByte(b)) return false;
    const la = runes(a).length, lb = runes(b).length;
    if (la - lb > 1 || lb - la > 1) return false;
    const pw = this.r.protein_words;
    if (has(pw, a) && pw[a] !== (has(pw, b) ? pw[b] : '')) return false;
    const d = lev(a, b, this.r.fuzzy_max_dist);
    return d <= this.r.fuzzy_max_dist && 1 - d / Math.max(la, lb) >= this.r.fuzzy_min_similarity;
  }

  private matchDish(toks: Token[], i: number): [Dish | null, number, boolean] {
    for (let n = this.maxLen; n >= 1; n--) {
      const ws = this.words(toks, i, n);
      if (!ws) continue;
      const term = ws.join(' ');
      const d = this.dish.get(term);
      if (d) return [d, n, false];
      const last = ws[n - 1];
      for (const suf of ['s', 'es']) {
        if (last.endsWith(suf)) {
          const alt = last.slice(0, -suf.length);
          if (alt !== '') { const a = this.dish.get([...ws.slice(0, n - 1), alt].join(' ')); if (a) return [a, n, false]; }
        }
      }
      if (this.filler.has(term) || (this.unitOf.get(term) ?? '') !== '' || (this.oilOf.get(term) ?? '') !== '' || this.small.has(term)) continue;
      let best = '', bestD = 1 << 30;
      for (const c of this.byWords.get(n) ?? []) {
        if (this.noFuzzyCat.has(this.dish.get(c)!.category ?? "")) continue; // e.g. a typo never turns into a fruit
        const cw = fields(c);
        let ok = true, dist = 0;
        for (let k = 0; k < cw.length; k++) {
          if (!this.fuzzyWord(ws[k], cw[k])) { ok = false; break; }
          dist += lev(ws[k], cw[k], 3);
        }
        if (ok && (dist < bestD || (dist === bestD && c < best))) { best = c; bestD = dist; }
      }
      if (best !== '') return [this.dish.get(best)!, n, true];
    }
    return [null, 0, false];
  }

  parse(text: string): ParseResult {
    const toks = this.tokenize(text);
    const items: It[] = [];
    const unmatched: string[] = [];
    let pd = emptyPending();
    let unk: string[] = [];
    let clause = 0;
    let joined = false;
    let leftover = 0;
    const flushUnk = () => {
      if (unk.length === 0) return;
      const span = unk.join(' ');
      unk = [];
      leftover++;
      const g = this.genericProtein(span, clause);
      if (g) { items.push(g); return; }
      // only real words (3+ letters, not stopwords) become a placeholder span; a leading count is kept with it
      const keep: string[] = [];
      fields(span).forEach((w, k) => {
        if (k === 0 && goParseFloat(w) !== null) { keep.push(w); return; }
        if (runes(w).length >= this.r.min_placeholder_len && !this.stop.has(w)) keep.push(w);
      });
      if (keep.length === 0 || (keep.length === 1 && goParseFloat(keep[0]) !== null)) return;
      unmatched.push(keep.join(' '));
    };
    const last = (): It | undefined => items[items.length - 1];
    const setLast = (x: It) => { items[items.length - 1] = x; };
    const push = (its: It[]) => {
      for (const x of its) {
        x.clause = clause;
        x.joined = joined && items.length > 0 && items[items.length - 1].clause === clause;
      }
      items.push(...its);
      joined = false;
    };
    for (let i = 0; i < toks.length; i++) {
      const t = toks[i];
      if (t.sep) { flushUnk(); clause++; joined = false; continue; }
      if (t.mult !== 0) {
        if (items.length > 0) {
          const li0 = items.length - 1;
          for (let k = items.length - 1; k >= 0; k--) {
            items[k] = { ...this.rescale(items[k], items[k].quantity * t.mult, items[k].unit), explicit: true };
            const li = items[li0];
            const it = items[k];
            if (!li.from_combo || it.from_combo !== li.from_combo || it.matched_text !== li.matched_text) break;
          }
        } else { pd.qty = t.mult; pd.hasQty = true; }
        continue;
      }
      if (has(this.r.protein_words, t.w) && this.attachProtein(t.w, items)) continue;
      if (this.formWord.has(t.w) && !this.dish.has(t.w)) {
        const li = last();
        if (li && !li.explicit && this.isProteinWord(li.matched_text) && !li.from_combo) {
          let span = li.matched_text + ' ' + t.w;
          while (i + 1 < toks.length && this.formWord.has(toks[i + 1].w)) { i++; span += ' ' + toks[i].w; }
          const g = this.genericProtein(span, li.clause ?? 0);
          if (g) { g.quantity = li.quantity; g.explicit = li.explicit; setLast(g); continue; }
        }
        const l2 = last();
        if (l2 && l2.clause === clause && unk.length === 0 && !l2.from_combo) {
          const g = this.applyForm(l2, t.w);
          if (g) setLast(g);
          else l2.matched_text += ' ' + t.w;
          continue;
        }
      }
      if (!t.isN || t.w === '') {
        let [d, n, fz] = this.matchDish(toks, i);
        if (d) {
          const matched = toks.slice(i, i + n).map((x) => this.word(x));
          if (this.fat.has(d.id) && i + n < toks.length && this.oilSuf.has(toks[i + n].w)) {
            flushUnk();
            const li = last();
            if (li && li.oil_level !== '') setLast(this.withOil(li, 'extra'));
            else pd.oil = 'extra';
            i += n;
            continue;
          }
          if (this.eggWord.has(matched.join(' '))) {
            const [j, ed] = this.eggDishAhead(toks, i + n);
            if (ed) {
              flushUnk();
              let eggs = 1;
              if (pd.hasQty) eggs = pd.qty * (pd.factor === 0 ? 1 : pd.factor);
              pd = { ...emptyPending(), qty: eggs / this.r.eggs_per_portion[ed.id], hasQty: true, oil: pd.oil };
              push(this.build(ed, pd, wordsOf(toks.slice(i, j + 1), (x) => this.word(x)).join(' '), false));
              pd = emptyPending();
              i = j;
              continue;
            }
          }
          const orig = d;
          let styleIgnored = false;
          for (const st of pd.style) {
            const sv = this.variantFromUnk(d, [st]);
            if (sv) d = sv; else styleIgnored = true;
          }
          const v = this.variantFromUnk(d, unk);
          if (v) { d = v; unk = unk.slice(0, -1); }
          flushUnk();
          d = this.proteinVariant(d, toks, i, n, items);
          let skip: number;
          [d, skip] = this.variantAhead(d, toks, i + n);
          const built = this.build(d, pd, matched.join(' '), fz);
          for (const b of built) { if (d !== orig) pen(b, 'variant'); if (styleIgnored) pen(b, 'style_ignored'); }
          push(built);
          pd = emptyPending();
          i += n - 1 + skip;
          continue;
        }
      }
      if (t.isN) {
        const li = last();
        if (li && !li.explicit && (this.r.eggs_per_portion[li.dish_id] ?? 0) > 0 && i + 1 < toks.length && this.eggWord.has(toks[i + 1].w)) {
          setLast({ ...this.rescale(li, t.num / this.r.eggs_per_portion[li.dish_id], li.unit), explicit: true });
          i++;
          while (i + 1 < toks.length && (this.genitive.has(toks[i + 1].w) || this.oilSuf.has(toks[i + 1].w))) i++;
          continue;
        }
        const tgt = this.trailTarget(items);
        if (tgt >= 0 && !pd.hasQty && (this.trailing(toks, i) || this.countBetween(items, tgt, toks, i))) {
          let u = '', f = 1;
          if (i + 1 < toks.length && !toks[i + 1].sep) {
            const [uu, ff] = this.unitFor(toks[i + 1].w);
            if (uu !== '') { u = uu; f = ff; i++; }
          }
          const between = !this.trailing(toks, i);
          this.applyTrailing(items, tgt, t.num * f, u);
          const k = Math.min(tgt, items.length - 1);
          if (k >= 0) { pen(items[k], 'trailing_qty'); if (between) pen(items[k], 'count_between'); }
          continue;
        }
        if (t.w !== '' && (i + 1 >= toks.length || toks[i + 1].sep)) continue;
        if (pd.hasQty) leftover++; // two numbers in a row: one is unused
        if (pd.hasQty) pd.qty *= t.num; else { pd.qty = t.num; pd.hasQty = true; }
        continue;
      }
      const w = t.w;
      const [u, f] = this.unitFor(w);
      if (u !== '') {
        if (!pd.hasQty) { pd.qty = 1; pd.hasQty = true; }
        pd.unit = u; pd.factor = f;
        continue;
      }
      if (this.small.has(w)) { pd.small = true; continue; }
      const lvl = this.oilOf.get(w);
      if (lvl !== undefined) {
        const li = last();
        if (li && lvl !== 'extra' && i + 1 < toks.length && this.oilNoun.has(toks[i + 1].w) && li.oil_level !== '') {
          setLast(this.withOil(li, lvl as OilLevel));
          i++;
          continue;
        }
        pd.oil = lvl;
        continue;
      }
      if (this.oilNoun.has(w) && i + 1 < toks.length && this.oilSuf.has(toks[i + 1].w)) {
        const li = last();
        if (li && li.oil_level !== '') setLast(this.withOil(li, 'extra'));
        else pd.oil = 'extra';
        i++;
        continue;
      }
      if (this.style.has(w)) {
        // cooking-style words are modifiers, never items
        let j = i + 1;
        while (j < toks.length && this.style.has(toks[j].w)) j++;
        const [nextDish] = this.matchDish(toks, j);
        if (nextDish) { pd.style.push(w); continue; } // "steamed momos": applies to the next dish
        const li = last();
        if (li && li.clause === clause && !li.explicit && this.isProteinWord(li.matched_text) && !li.from_combo) {
          const g = this.genericProtein(li.matched_text + ' ' + w, li.clause ?? 0);
          if (g) { setLast(g); continue; }
        }
        if (li && li.clause === clause && unk.length === 0) {
          const g = this.applyForm(li, w);
          if (g) { pen(g, 'variant'); setLast(g); } else { li.matched_text += ' ' + w; pen(li, 'style_ignored'); }
          continue;
        }
        pd.style.push(w);
        continue;
      }
      if (this.connector.has(w)) { flushUnk(); joined = true; continue; }
      if (this.filler.has(w) || this.oilSuf.has(w) || this.genitive.has(w) || this.stuffing.has(w)) continue;
      if (pd.hasQty && unk.length === 0) unk.push(fmt(pd.qty));
      pd = emptyPending();
      // unknown word right after a bare protein word ("paneer lababdar"): the protein goes into the span (-> generic item).
      if (unk.length === 0) {
        const li = last();
        if (li && !li.explicit && i > 0 && !toks[i - 1].sep && li.matched_text === this.word(toks[i - 1]) && this.isProteinWord(li.matched_text)) {
          unk.push(li.matched_text);
          items.pop();
        } else if (li && li.clause === clause) pen(li, 'leftover_nearby');
      }
      unk.push(w);
    }
    flushUnk();
    if (pd.hasQty) leftover++; // a number nothing used
    const present = new Set(items.map((x) => x.dish_id));
    for (const it of items) {
      it.explicit = false;
      if (leftover > 0 || unmatched.length > 0) pen(it, 'leftover_in_meal');
      const sides = this.r.typical_sides[it.dish_id];
      if (sides && !sides.some((sd) => present.has(sd))) pen(it, 'missing_side');
    }
    const out: Item[] = items.map((x) => this.finish(x));
    return { items: out, unmatched, leftover };
  }

  private applyForm(li: It, form: string): It | null {
    const d = this.dishById(li.dish_id);
    if (!d) return null;
    const mk = (nd: Dish, generic: boolean): It => {
      const it: It = { ...blank(), dish_id: nd.id, name: nd.name, matched_text: li.matched_text + ' ' + form, data_source: nd.source, source_note: nd.source_note,
        generic, clause: li.clause, joined: li.joined, explicit: li.explicit, fuzzy: li.fuzzy };
      const q = li.explicit && (li.unit === 'count' || li.unit === 'piece') ? li.quantity : 1;
      return this.compute(nd, it, q, '');
    };
    for (const name of [d.name, ...(d.aliases ?? [])]) {
      const v = this.dish.get(name + ' ' + form);
      if (v && v !== d) return mk(v, false);
    }
    if (!this.r.wrap_forms.includes(form)) return null;
    const pw = this.r.protein_words;
    for (const w of fields(d.name)) {
      if (has(pw, w)) {
        const kind = pw[w];
        // NOTE: Go ranges over a map here (random order); only matters if two protein words of the same kind both have a "<word> roll" row.
        for (const [p2, k] of Object.entries(pw)) {
          if (k !== kind) continue;
          const v = this.dish.get(p2 + ' roll');
          if (v) return mk(v, false);
        }
        const g = this.dishById(this.r.generic_protein_dish[kind] ?? '');
        if (g) return mk(g, true);
      }
    }
    const g = this.dishById(this.r.generic_wrap_dish);
    return g ? mk(g, true) : null;
  }

  private isProteinWord(s: string) { return has(this.r.protein_words, s); }

  private genericProtein(span: string, clause: number): It | null {
    let ws = fields(span);
    let qty = 1;
    const v = goParseFloat(ws[0]);
    if (v !== null && v > 0) { qty = v; ws = ws.slice(1); }
    for (const w of ws) {
      if (has(this.r.protein_words, w)) {
        const d = this.dishById(this.r.generic_protein_dish[this.r.protein_words[w]] ?? '');
        if (!d) return null;
        const it: It = { ...blank(), dish_id: d.id, name: d.name, matched_text: span, data_source: d.source, source_note: d.source_note, generic: true, clause };
        return this.compute(d, it, qty, '');
      }
    }
    return null;
  }

  private variantFromUnk(d: Dish, unk: string[]): Dish | null {
    if (unk.length === 0) return null;
    const w = unk[unk.length - 1];
    for (const name of [d.name, ...(d.aliases ?? [])]) {
      const fs = fields(name);
      for (const base of [name, fs[fs.length - 1]]) {
        const v = this.dish.get(w + ' ' + base);
        if (v && v !== d) return v;
      }
    }
    return null;
  }

  private variantAhead(d: Dish, toks: Token[], j: number): [Dish, number] {
    let cand = '';
    let stuffed = false;
    let k = j;
    for (; k < toks.length && k < j + 4 && !toks[k].sep && !toks[k].isN; k++) {
      const w = toks[k].w;
      if (this.stuffing.has(w) || this.genitive.has(w)) { if (w !== 'with') stuffed = true; }
      else if (cand === '') cand = w;
      else k = toks.length + 1;
      if (k > toks.length) break;
      if (cand !== '' && stuffed) break;
    }
    if (cand === '' || k > toks.length) return [d, 0];
    if (!stuffed && !this.modifier.has(cand)) return [d, 0];
    for (const name of [d.name, ...(d.aliases ?? [])]) {
      const v = this.dish.get(cand + ' ' + name);
      if (v && v !== d) {
        let e = k;
        if (e >= toks.length) e = toks.length - 1;
        while (e + 1 < toks.length && (this.stuffing.has(toks[e + 1].w) || this.genitive.has(toks[e + 1].w)) && toks[e + 1].w !== 'with') e++;
        return [v, e - j + 1];
      }
    }
    return [d, 0];
  }

  private eggDishAhead(toks: Token[], j: number): [number, Dish | null] {
    while (j < toks.length && !toks[j].sep && (this.genitive.has(toks[j].w) || this.oilSuf.has(toks[j].w) || this.filler.has(toks[j].w))) j++;
    if (j >= toks.length || toks[j].sep) return [0, null];
    const [d, n] = this.matchDish(toks, j);
    if (!d || !(this.r.eggs_per_portion[d.id] ?? 0)) return [0, null];
    return [j + n - 1, d];
  }

  /** Sets the response source and needs_confirmation; strips internal fields. */
  private finish(x: It): Item {
    const d = this.dishById(x.dish_id);
    const source: ItemSource = x.generic || d?.needs_confirm ? 'generic' : x.fuzzy ? 'did_you_mean' : 'table';
    const it: It = this.sanity({ ...x, source });
    if (it.fuzzy) pen(it, 'fuzzy');
    if (it.source === 'generic') pen(it, 'generic');
    if (it.from_combo) pen(it, 'combo_or_split');
    const conf = this.r.confidence;
    let c = 1;
    for (const f of it.pens ?? []) c += has(conf, f) ? conf[f] : conf.leftover_in_meal;
    it.confidence = Math.max(0, round(c, 2));
    const pens = it.pens ?? [];
    if (pens.length) it.flags = [...pens];
    // leftovers, splits and combos always need a look, whatever the score
    const forced = pens.some((f) => f === 'leftover_in_meal' || f === 'combo_or_split' || f === 'leftover_nearby');
    if (it.confidence < conf.threshold || forced) { it.needs_confirmation = true; if (it.source === 'table') it.source = 'did_you_mean'; }
    it.needs_confirmation = it.source !== 'table' || it.needs_confirmation;
    const { explicit: _e, generic: _g, clause: _c, joined: _j, pens: _p, ...base } = it;
    return base;
  }

  private sanity<T extends It>(it: T): T {
    const d = this.dishById(it.dish_id);
    let mult = this.r.sanity.max_portion_multiple;
    if (d && (d.unit === 'count' || it.unit === 'piece')) mult = this.r.sanity.max_count_multiple; // 4-6 rotis is normal
    if (!d || (it.kcal.best <= this.r.sanity.max_item_kcal && it.grams <= mult * d.portion_grams)) return it;
    pen(it, 'sanity');
    const alts: Alternative[] = [];
    const alt = (q: number, u: string, label: string) => {
      const c = this.compute(d, blank(), q, u);
      alts.push({ quantity: q, unit: c.unit, kcal: c.kcal.best, label });
    };
    if ((d.piece_grams ?? 0) > 0 && it.unit !== 'piece') alt(it.quantity, 'piece', 'pieces instead of ' + it.unit);
    alt(1, d.unit, 'one standard portion');
    return { ...it, needs_confirmation: true, alternatives: [...(it.alternatives ?? []), ...alts] };
  }

  private proteinVariant(d: Dish, toks: Token[], i: number, n: number, items: It[]): Dish {
    const pw = this.r.protein_words;
    const tryW = (w: string): Dish | null => {
      if (!Object.prototype.hasOwnProperty.call(pw, w)) return null;
      for (const name of [d.name, ...(d.aliases ?? [])]) {
        const v = this.dish.get(w + ' ' + name);
        if (v && v !== d) return v;
      }
      return null;
    };
    for (let k = i - 1; k >= 0 && !toks[k].sep; k--) {
      const w = toks[k].w;
      if (this.filler.has(w) || this.style.has(w)) continue;
      const v = tryW(w);
      if (v) {
        const li = items[items.length - 1];
        if (li && li.matched_text === w && !li.explicit) items.pop();
        return v;
      }
      break;
    }
    let j = i + n;
    while (j < toks.length && !toks[j].sep && this.filler.has(toks[j].w)) j++;
    if (j < toks.length && !toks[j].sep && Object.prototype.hasOwnProperty.call(pw, toks[j].w)) {
      const v = tryW(toks[j].w);
      if (v) return v;
    }
    return d;
  }

  private attachProtein(w: string, items: It[]): boolean {
    const li = items[items.length - 1];
    if (!li) return false;
    return li.dish_id.startsWith(this.r.protein_words[w] + '_') || li.name.startsWith(w + ' ');
  }

  private trailTarget(items: It[]): number {
    const n = items.length;
    if (n === 0) return -1;
    const li = items[n - 1];
    if (li.explicit) return -1;
    if (this.fat.has(li.dish_id)) {
      for (let k = n - 2; k >= 0; k--) {
        if (!this.fat.has(items[k].dish_id)) return items[k].explicit ? -1 : k;
      }
    }
    return n - 1;
  }

  private applyTrailing(items: It[], k: number, qty: number, unit: string) {
    if (unit !== '') {
      const group = [k];
      for (let j = k; j > 0 && items[j].joined;) {
        j--;
        if (items[j].clause !== items[k].clause || items[j].explicit) break;
        if (this.fat.has(items[j].dish_id)) continue;
        group.push(j);
      }
      if (group.length > 1) {
        // one serving made of both parts: a combo row if the table has one...
        const combo = this.comboFor(items, group);
        if (combo) {
          const first = group[group.length - 1];
          let it: It = { ...blank(), dish_id: combo.id, name: combo.name, data_source: combo.source, source_note: combo.source_note, clause: items[k].clause, explicit: true };
          for (let g = group.length - 1; g >= 0; g--) it.matched_text = (it.matched_text + ' ' + items[group[g]].matched_text).trim();
          it = this.compute(combo, it, qty, unit);
          if (combo.oil_sensitive) it = this.withOil(it, 'normal');
          pen(it, 'combo_or_split');
          const keep: It[] = [];
          items.forEach((x, idx) => { if (idx === first) keep.push(it); else if (!group.includes(idx)) keep.push(x); });
          items.splice(0, items.length, ...keep);
          return;
        }
        // ...otherwise split one serving by each part's calorie share
        let sumK = 0;
        for (const g of group) sumK += this.dishById(items[g].dish_id)!.kcal;
        for (const g of group) {
          const d = this.dishById(items[g].dish_id)!;
          const share = sumK > 0 ? d.kcal / sumK : 1 / group.length;
          items[g] = { ...this.rescale(items[g], round(qty * share, 2), unit), explicit: true };
          pen(items[g], 'combo_or_split');
        }
        return;
      }
    }
    const it = items[k];
    const d = this.dishById(it.dish_id)!;
    if (!it.from_combo && (d.parts?.length ?? 0) > 0 && unit !== '' && unit !== d.unit) {
      const parts = this.expand(d, qty, unit, it.oil_level, it.matched_text, it.fuzzy);
      for (const pt of parts) pt.clause = it.clause;
      items.splice(k, 1, ...parts);
      return;
    }
    if (unit === '' && (d.piece_grams ?? 0) > 0) unit = 'piece';
    items[k] = { ...this.rescale(it, qty, unit), explicit: true };
  }

  /** a table row that is exactly these parts ("rajma" + "rice" -> rajma chawal) */
  private comboFor(items: It[], group: number[]): Dish | null {
    const want = new Set(group.map((g) => items[g].dish_id));
    for (const d of this.table) {
      if ((d.parts?.length ?? 0) !== want.size) continue;
      if (d.parts!.every((pt) => want.has(pt.dish_id))) return d;
    }
    return null;
  }

  private unitFor(w: string): [string, number] {
    const u = this.unitOf.get(w);
    if (u === undefined) return ['', 0];
    const ur = this.r.units[u];
    if (ur.as) return [ur.as, ur.factor ?? 0];
    return [u, 1];
  }

  private trailing(toks: Token[], i: number): boolean {
    let j = i + 1;
    if (j < toks.length && !toks[j].sep && this.unitFor(toks[j].w)[0] !== '') j++;
    while (j < toks.length && !toks[j].sep && this.filler.has(toks[j].w)) j++;
    return j >= toks.length || toks[j].sep;
  }

  private countBetween(items: It[], tgt: number, toks: Token[], i: number): boolean {
    if (i + 1 >= toks.length || toks[i + 1].sep || toks[i + 1].isN || (this.unitOf.get(toks[i + 1].w) ?? '') !== '') return false;
    const prev = this.dishById(items[tgt].dish_id);
    const [next] = this.matchDish(toks, i + 1);
    return !!prev && !!next && prev.unit === 'count' && next.unit !== 'count' && toks[i].w === '';
  }

  private unitGrams(d: Dish, unit: string): number {
    if (unit === '' || unit === d.unit || unit === 'count') return d.portion_grams;
    if (unit === 'piece') return (d.piece_grams ?? 0) > 0 ? d.piece_grams! : d.portion_grams;
    return this.r.units[unit]?.grams ?? 0;
  }

  private build(d: Dish, pd: Pending, matched: string, fuzzy: boolean): It[] {
    let qty = 1;
    if (pd.hasQty) qty = pd.qty * (pd.factor === 0 ? 1 : pd.factor);
    let unit = pd.unit;
    if (pd.small && !pd.hasQty && !this.fat.has(d.id)) qty = 0.5;
    if (this.fat.has(d.id) && !pd.hasQty) {
      qty = this.r.default_fat_spoons;
      if (pd.small || pd.oil === 'less') qty = this.r.small_fat_spoons;
      if (pd.oil === 'extra') qty = this.r.extra_fat_spoons;
    }
    let oil = pd.oil;
    let capped = false;
    if (this.fat.has(d.id)) { oil = ''; capped = (unit === '' || unit === 'spoon') && qty > this.r.max_fat_spoons; }
    if ((d.parts?.length ?? 0) > 0 && pd.unit !== '' && pd.unit !== d.unit) return this.expand(d, qty, unit, oil, matched, fuzzy);
    if ((d.piece_grams ?? 0) > 0 && pd.hasQty && (unit === '' || unit === 'count')) unit = 'piece';
    let it: It = { ...blank(), dish_id: d.id, name: d.name, matched_text: matched, data_source: d.source, source_note: d.source_note, fuzzy, explicit: pd.hasQty };
    it = this.compute(d, it, qty, unit);
    if (capped) { pen(it, 'capped'); it.needs_confirmation = true; }
    if (d.oil_sensitive) it = this.withOil(it, (oil || 'normal') as OilLevel);
    return [it];
  }

  private expand(d: Dish, qty: number, unit: string, oil: string, matched: string, fuzzy: boolean): It[] {
    let grams = qty * this.unitGrams(d, unit);
    if (unit === 'gram') grams = qty;
    const f = grams / d.portion_grams;
    const out: It[] = [];
    for (const pt of d.parts ?? []) {
      const pdd = this.dishById(pt.dish_id)!;
      let it: It = { ...blank(), dish_id: pdd.id, name: pdd.name, matched_text: matched, data_source: pdd.source, source_note: pdd.source_note, fuzzy, from_combo: d.id, explicit: true };
      it = this.compute(pdd, it, round(pt.qty * f, 2), pt.unit);
      if (pdd.oil_sensitive) it = this.withOil(it, (oil || 'normal') as OilLevel);
      out.push(it);
    }
    return out;
  }

  private compute<T extends Item>(d: Dish, it: T, qty: number, unit: string): T {
    if (unit === '') unit = d.unit;
    if (this.fat.has(d.id)) {
      if (unit !== 'spoon' && unit !== 'gram') unit = 'spoon';
      qty = unit === 'spoon' ? Math.min(qty, this.r.max_fat_spoons) : Math.min(qty, this.r.max_fat_spoons * this.r.units.spoon.grams);
    }
    let grams = qty * this.unitGrams(d, unit);
    if (unit === 'gram') grams = qty;
    const scale = grams / d.portion_grams;
    return {
      ...it, quantity: round(qty, 2), unit, grams: round(grams, 0),
      kcal: { low: round(d.kcal_low * scale, 0), best: round(d.kcal * scale, 0), high: round(d.kcal_high * scale, 0) },
      protein_g: { low: round(d.protein_low * scale, 1), best: round(d.protein_g * scale, 1), high: round(d.protein_high * scale, 1) },
      carbs_g: round((d.carbs_g ?? 0) * scale, 1), fat_g: round((d.fat_g ?? 0) * scale, 1),
    };
  }

  rescale<T extends Item>(it: T, qty: number, unit: string): T {
    const d = this.dishById(it.dish_id)!;
    const lvl = it.oil_level;
    let n = this.compute(d, it, qty, unit);
    n.oil_level = '';
    if (lvl !== '') n = this.withOil(n, lvl);
    return n;
  }

  withOil<T extends Item>(it: T, lvl: OilLevel): T {
    const d = this.dishById(it.dish_id)!;
    const n = this.compute(d, it, it.quantity, it.unit);
    n.oil_level = lvl;
    const delta = (this.r.oil_kcal_per_150g * n.grams) / 150;
    const k = n.kcal;
    if (lvl === 'less') {
      n.kcal = { low: Math.max(0, round(k.low - delta, 0)), best: Math.max(0, round(k.best - delta, 0)), high: k.high - round(delta / 2, 0) };
      n.fat_g = Math.max(0, round(n.fat_g - delta / 9, 1));
    } else if (lvl === 'extra') {
      n.kcal = { low: k.low + round(delta / 2, 0), best: round(k.best + delta, 0), high: round(k.high + delta * 1.5, 0) };
      n.fat_g = round(n.fat_g + delta / 9, 1);
    }
    return n;
  }

  /** Mirror of Go Recompute: build an item from an edited chip. Throws on bad input. */
  recompute(dishID: string, qty: number, unit: string, oil: string): Item {
    const d = this.dishById(dishID);
    if (!d) throw new Error('unknown dish_id');
    if (unit !== '' && !UNITS.includes(unit)) throw new Error('unit must be one of ' + UNITS.join(', '));
    if (qty <= 0 || qty > 5000) throw new Error('quantity out of range');
    let it: Item = { ...blank(), dish_id: d.id, name: d.name, matched_text: d.name, source: 'table', data_source: d.source, source_note: d.source_note };
    it = this.compute(d, it, qty, unit);
    if (d.oil_sensitive) {
      if (oil === '') oil = 'normal';
      if (!['less', 'normal', 'extra'].includes(oil)) throw new Error('oil_level must be less, normal or extra');
      it = this.withOil(it, oil as OilLevel);
    }
    it = this.sanity(it);
    delete (it as It).pens;
    if (d.needs_confirm) it = { ...it, source: 'generic', needs_confirmation: true };
    return it;
  }

  /** Mirror of Go Unknown: placeholder for unrecognised text. Never 0 kcal; always needs confirmation. */
  unknown(span: string): Item {
    const u = this.r.unknown_item;
    return { ...blank(), name: span, matched_text: span, quantity: 1, unit: 'count', source: 'generic', data_source: 'estimate',
      source_note: 'Placeholder for unrecognised food; please confirm or enter your own numbers',
      kcal: { low: u.kcal[0], best: u.kcal[1], high: u.kcal[2] }, protein_g: { low: u.protein_g[0], best: u.protein_g[1], high: u.protein_g[2] },
      needs_confirmation: true };
  }

  /** App edit helper: recompute an item from the table, keeping matched text; re-runs the sanity check. */
  edit(it: Item, ch: { dishId?: string; quantity?: number; unit?: string; oil?: OilLevel }): Item {
    const d = this.dishById(ch.dishId ?? it.dish_id)!;
    const n = this.recompute(d.id, ch.quantity ?? it.quantity, ch.unit ?? (ch.dishId ? d.unit : it.unit), d.oil_sensitive ? ch.oil || it.oil_level || 'normal' : '');
    return { ...n, matched_text: it.matched_text };
  }
}

export const UNITS = ['count', 'piece', 'katori', 'spoon', 'plate', 'glass', 'gram'];
const blank = (): Item => ({
  dish_id: '', name: '', matched_text: '', quantity: 0, unit: '', grams: 0, oil_level: '',
  kcal: { low: 0, best: 0, high: 0 }, protein_g: { low: 0, best: 0, high: 0 }, carbs_g: 0, fat_g: 0,
  source: 'table', data_source: '', source_note: '', fuzzy: false, from_combo: undefined, needs_confirmation: false, alternatives: undefined, ai_estimate: false, learned: false,
});

function wordsOf(ts: Token[], word: (t: Token) => string): string[] {
  return ts.filter((t) => !t.sep).map(word);
}

export function lev(as: string, bs: string, max: number): number {
  const a = runes(as), b = runes(bs);
  const d = a.length - b.length;
  if (d > max || -d > max) return max + 1;
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = new Array<number>(b.length + 1);
    cur[0] = i; let lo = cur[0];
    for (let j = 1; j <= b.length; j++) {
      const c = a[i - 1] === b[j - 1] ? 0 : 1;
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + c);
      lo = Math.min(lo, cur[j]);
    }
    if (lo > max) return max + 1;
    prev = cur;
  }
  return prev[b.length];
}

export function totals(items: Pick<Item, 'kcal' | 'protein_g'>[]): [Range, Range] {
  const k = { low: 0, best: 0, high: 0 }, p = { low: 0, best: 0, high: 0 };
  for (const it of items) {
    k.low += it.kcal.low; k.best += it.kcal.best; k.high += it.kcal.high;
    p.low += it.protein_g.low; p.best += it.protein_g.best; p.high += it.protein_g.high;
  }
  return [k, { low: round(p.low, 1), best: round(p.best, 1), high: round(p.high, 1) }];
}
